#!/usr/bin/env python3
"""
patch_s182_s183_combined.py - Ayat Studio S182 + S183 in one file (run from repo root, after S181)
  S182: Whisper / auto-sync on the main screen
  S183: text block on the timeline (begin / stop) + text bar on the main screen
Each part is idempotent and checks its anchors before writing; if S182 fails, S183 is not run.
"""
import sys
PARTS = [('S182', '#!/usr/bin/env python3\n"""\npatch_s182_whisper_on_main_screen.py - Ayat Studio S182 (run from repo root, after S181)\n\nWhisper / auto-sync was only reachable inside the "الفيديو" tab, so on the main\nscreen you could not see it. This patch puts it where you work:\n  1. The empty ayah track on the timeline now holds a gold button\n     «مزامنة تلقائية (Whisper)». Tap it and the sync starts.\n  2. Selecting the main clip (tap the video / audio track) shows three new\n     buttons at the START of its bar: مزامنة تلقائية - تعرّف من الصوت - دقة التعرّف\n     (the Whisper model picker).\n  3. The clip bar shows ~6 buttons at once instead of 4-5, so the rest are not hidden.\nIdempotent; every anchor is verified before anything is written.\n"""\nimport os, sys\n\nMARK = \'PATCH_S182_WHISPER_MAIN\'\nTL = \'lib/widgets/pro_timeline.dart\'\nHOME = \'lib/screens/home_screen.dart\'\nfor p in (TL, HOME):\n    if not os.path.exists(p):\n        sys.exit(\'Run from the repo root (missing %s).\' % p)\ntl = open(TL, encoding=\'utf-8\').read()\nhome = open(HOME, encoding=\'utf-8\').read()\nif MARK in tl or MARK in home:\n    print(\'  OK      already applied\'); sys.exit(0)\nif \'PATCH_S181_CLIPTOUCH\' not in tl or \'PATCH_S181_CLIPTOUCH\' not in home:\n    sys.exit(\'S181 is not applied yet.\')\n\nTL_EDITS = [\n (\'param\',\n  "  final VoidCallback? onAddMedia;\\n",\n  "  final VoidCallback? onAddMedia;\\n  final VoidCallback? onAutoSync; // " + MARK + "\\n"),\n (\'ctor\',\n  "    this.onAddMedia,\\n  });\\n",\n  "    this.onAddMedia,\\n    this.onAutoSync, // " + MARK + "\\n  });\\n"),\n (\'empty ayah lane\',\n  """          if (tl.isEmpty)\n            const Positioned.fill(\n              child: Padding(\n                padding: EdgeInsets.only(left: 10),\n                child: Align(\n                  alignment: Alignment.centerLeft,\n                  child: Text(\n                    \'المزامنة التلقائية تملأ هذا المسار بالآيات\',\n                    textDirection: TextDirection.rtl,\n                    style: TextStyle(\n                        fontSize: 10.5, color: AyatColors.parchmentDim),\n                  ),\n                ),\n              ),\n            ),\n""",\n  """          if (tl.isEmpty)\n            Positioned.fill(\n              child: Padding(\n                padding: const EdgeInsets.only(left: 10),\n                child: Align(\n                  alignment: Alignment.centerLeft,\n                  // """ + MARK + """: the lane itself offers the sync\n                  child: widget.onAutoSync == null\n                      ? const Text(\n                          \'المزامنة التلقائية تملأ هذا المسار بالآيات\',\n                          textDirection: TextDirection.rtl,\n                          style: TextStyle(\n                              fontSize: 10.5, color: AyatColors.parchmentDim),\n                        )\n                      : GestureDetector(\n                          behavior: HitTestBehavior.opaque,\n                          onTap: () {\n                            HapticFeedback.selectionClick();\n                            widget.onAutoSync!();\n                          },\n                          child: Container(\n                            padding: const EdgeInsets.symmetric(\n                                horizontal: 12, vertical: 6),\n                            decoration: BoxDecoration(\n                              color: AyatColors.goldBright,\n                              borderRadius: BorderRadius.circular(16),\n                            ),\n                            child: const Row(\n                              mainAxisSize: MainAxisSize.min,\n                              children: [\n                                Icon(Icons.auto_awesome,\n                                    size: 15, color: AyatColors.ink),\n                                SizedBox(width: 6),\n                                Text(\n                                  \'مزامنة تلقائية (Whisper)\',\n                                  style: TextStyle(\n                                      fontSize: 11.5,\n                                      fontWeight: FontWeight.w800,\n                                      color: AyatColors.ink),\n                                ),\n                              ],\n                            ),\n                          ),\n                        ),\n                ),\n              ),\n            ),\n"""),\n]\n\nHOME_EDITS = [\n (\'wire timeline button\',\n  "          onAddMedia: _addMediaSheet,\\n",\n  "          onAddMedia: _addMediaSheet,\\n          onAutoSync: _busy ? null : _autoSync, // " + MARK + "\\n"),\n (\'whisper buttons in main clip bar\',\n  "        (Icons.check_circle_outline, \'تم\', () => setState(() => _selMain = false), false),\\n        (Icons.first_page, \'قص البداية\', () => _trimMain(head: true), false),\\n",\n  "        (Icons.check_circle_outline, \'تم\', () => setState(() => _selMain = false), false),\\n"\n  "        // " + MARK + ": Whisper on the main screen\\n"\n  "        (Icons.auto_awesome, \'مزامنة تلقائية\', () { if (!_busy) _autoSync(); }, state.timelineActive),\\n"\n  "        (Icons.manage_search, \'تعرّف من الصوت\', () { if (!_busy) _detectFromVideo(); }, false),\\n"\n  "        (Icons.hearing, \'دقة التعرّف\', () { if (!_busy) _showModelSizePicker(); }, false),\\n"\n  "        (Icons.first_page, \'قص البداية\', () => _trimMain(head: true), false),\\n"),\n (\'bar button width\',\n  "              child: SizedBox(\\n                width: 76,\\n                child: Column(\\n                  mainAxisAlignment: MainAxisAlignment.center,\\n                  children: [\\n                    Icon(it.$1, size: 23, color: col),\\n",\n  "              child: SizedBox(\\n                width: min(76.0, MediaQuery.of(context).size.width / 6.4), // " + MARK + "\\n                child: Column(\\n                  mainAxisAlignment: MainAxisAlignment.center,\\n                  children: [\\n                    Icon(it.$1, size: 23, color: col),\\n"),\n]\n\nMANY = {\'bar button width\': 2}  # the seg bar and the new clip bar share this code\nbad = []\nfor name, text, eds in ((\'tl\', tl, TL_EDITS), (\'home\', home, HOME_EDITS)):\n    for label, old, _ in eds:\n        n = text.count(old)\n        if n != MANY.get(label, 1):\n            bad.append(\'%s: %s (found %d)\' % (name, label, n))\nif bad:\n    sys.exit(\'Anchor check failed, nothing written:\\n  \' + \'\\n  \'.join(bad))\nfor label, old, new in TL_EDITS:\n    tl = tl.replace(old, new, 1); print(\'  PATCHED pro_timeline.dart -\', label)\nfor label, old, new in HOME_EDITS:\n    home = home.replace(old, new); print(\'  PATCHED home_screen.dart -\', label)\nopen(TL, \'w\', encoding=\'utf-8\').write(tl)\nopen(HOME, \'w\', encoding=\'utf-8\').write(home)\nprint(\'S182 applied. Next: git add -A && git commit -m "S182: Whisper on the main screen" && git push\')\n'), ('S183', '#!/usr/bin/env python3\n"""\npatch_s183_text_bar_and_text_block.py - Ayat Studio S183 (run from repo root, after S181 + S182)\n\nTwo things, both about the text on your video:\n\n  1) TEXT ON THE TIMELINE, WITH START / STOP\n     The text you typed now appears on the timeline as a block (text track) that\n     shows the text. Select it and drag its two gold edges with your finger to\n     decide when it BEGINS and when it STOPS. The preview obeys the window too\n     (the text appears and disappears with the same transition as the export),\n     and the export already used this window.\n\n  2) TEXT BAR ON THE MAIN SCREEN\n     Tap the text on the stage (or its block on the timeline) and the bottom bar\n     becomes a text bar: أصغر / أكبر (size), الخط (all fonts, not 9 hidden in a\n     tab), الموضع (top / middle / bottom), انتقال (appear / disappear style),\n     يبدأ هنا / ينتهي هنا (window from the playhead), كامل المدة, الروح.\n     Pinch size range is also wider (0.4x to 3x instead of 0.6x to 1.8x).\n\nIdempotent; every anchor is verified before anything is written.\n"""\nimport os, sys\n\nMARK = \'PATCH_S183_TEXT_BAR\'\nF = {\n    \'state\': \'lib/models/studio_state.dart\',\n    \'tl\': \'lib/widgets/pro_timeline.dart\',\n    \'home\': \'lib/screens/home_screen.dart\',\n    \'stage\': \'lib/widgets/stage_preview.dart\',\n}\nfor p in F.values():\n    if not os.path.exists(p):\n        sys.exit(\'Run from the repo root (missing %s).\' % p)\nT = {k: open(p, encoding=\'utf-8\').read() for k, p in F.items()}\nif any(MARK in t for t in T.values()):\n    print(\'  OK      already applied\'); sys.exit(0)\nfor k in (\'tl\', \'home\', \'state\'):\n    if \'PATCH_S181_CLIPTOUCH\' not in T[k]:\n        sys.exit(\'S181 is not applied yet.\')\n\n# ------------------------------------------------------------------ state\nSTATE_OLD = """    final next = [...textTimeCues]..insert(index + 1, copy);\n    textTimeCues = next;\n    notifyListeners();\n  }\n"""\nSTATE_NEW = STATE_OLD + """\n  // PATCH_S183_TEXT_BAR: the window (begin / stop) of the typed text. Both ends\n  // are always set together, because the exporter only honours the window when\n  // it has both. [dur] is the clip length in seconds.\n  void setTextWindow(double dur, {double? start, double? end}) {\n    if (dur <= 0.3) return;\n    var s = start ?? textTimeStartOverride ?? 0.0;\n    var e = end ?? textTimeEndOverride ?? dur;\n    s = s < 0.0 ? 0.0 : (s > dur ? dur : s);\n    e = e < 0.0 ? 0.0 : (e > dur ? dur : e);\n    if (e - s < 0.3) {\n      if (start != null) {\n        s = e - 0.3 < 0.0 ? 0.0 : e - 0.3;\n        if (e - s < 0.3) e = s + 0.3;\n      } else {\n        e = s + 0.3 > dur ? dur : s + 0.3;\n        if (e - s < 0.3) s = e - 0.3;\n      }\n    }\n    textTimeStartOverride = s;\n    textTimeEndOverride = e;\n    notifyListeners();\n  }\n\n  void clearTextWindow() {\n    textTimeStartOverride = null;\n    textTimeEndOverride = null;\n    notifyListeners();\n  }\n"""\n\n# --------------------------------------------------------------- timeline\nTL_LANE_OLD = """      if (!c && s.textTimeCues.isNotEmpty)\n        const _LaneSpec(\'text\', Icons.title, 32), // PATCH_S181_CLIPTOUCH\n"""\nTL_LANE_NEW = """      if (s.textTimeCues.isNotEmpty ||\n          (s.hasAyah && !(s.timelineActive && s.timeline.isNotEmpty)))\n        _LaneSpec(\'text\', Icons.title, c ? 26 : 32), // PATCH_S183_TEXT_BAR\n"""\n\nTL_TEXTLANE = """  Widget _textLane(double h, double w) {\n    final cues = widget.state.textTimeCues;\n    return GestureDetector(\n      behavior: HitTestBehavior.opaque,\n      onTapUp: (d) {\n        widget.onSelectSeg(-1);\n        _seekSec(d.localPosition.dx / _pps);\n      },\n      child: Stack(\n        children: [\n          for (var i = 0; i < cues.length; i++) _cueClip(i, h),\n          // PATCH_S183_TEXT_BAR: the typed text, as a block with begin / stop\n          if (cues.isEmpty && _showTypedBlock) _typedBlock(h),\n        ],\n      ),\n    );\n  }\n\n  bool get _showTypedBlock =>\n      widget.state.hasAyah &&\n      !(widget.state.timelineActive && widget.state.timeline.isNotEmpty);\n\n  double _tBase = 0;\n  double _tAccum = 0;\n\n  Widget _typedBlock(double h) {\n    final st = widget.state;\n    final a = (st.textTimeStartOverride ?? 0.0).clamp(0.0, _dur).toDouble();\n    final b = (st.textTimeEndOverride ?? _dur).clamp(0.0, _dur).toDouble();\n    final sel = st.stageTextSelected;\n    final w = math.max(6.0, (b - a) * _pps - 1);\n    return Positioned(\n      left: a * _pps,\n      width: w,\n      top: 2,\n      height: h - 4,\n      child: GestureDetector(\n        onTapUp: (d) {\n          widget.onSelectSeg(-1);\n          if (sel) {\n            st.clearStageSelection();\n          } else {\n            st.selectStageText();\n            _zoomIfNarrow(a, b);\n          }\n          _seekSec(a + d.localPosition.dx / _pps);\n          HapticFeedback.selectionClick();\n        },\n        child: Stack(\n          children: [\n            Positioned.fill(\n              child: Container(\n                padding: EdgeInsets.symmetric(horizontal: sel ? 24 : 6),\n                alignment: Alignment.centerLeft,\n                decoration: BoxDecoration(\n                  color: const Color(0xFF2C6B5A),\n                  borderRadius: BorderRadius.circular(6),\n                  border: Border.all(\n                    color: sel\n                        ? AyatColors.goldBright\n                        : const Color(0x66ECC875),\n                    width: sel ? 2 : 1,\n                  ),\n                ),\n                child: ClipRect(\n                  child: Text(\n                    st.ayahText,\n                    maxLines: 1,\n                    overflow: TextOverflow.clip,\n                    textDirection: TextDirection.rtl,\n                    style: const TextStyle(\n                        fontSize: 11.5,\n                        fontWeight: FontWeight.w700,\n                        color: AyatColors.parchment),\n                  ),\n                ),\n              ),\n            ),\n            if (sel) ...[\n              _typedHandle(true, w),\n              _typedHandle(false, w),\n            ],\n          ],\n        ),\n      ),\n    );\n  }\n\n  Widget _typedHandle(bool isStart, double clipW) {\n    return Positioned(\n      left: isStart ? 0 : null,\n      right: isStart ? null : 0,\n      top: 0,\n      bottom: 0,\n      width: _handleW(clipW),\n      child: GestureDetector(\n        behavior: HitTestBehavior.opaque,\n        onHorizontalDragStart: (_) {\n          final st = widget.state;\n          st.pushHistory();\n          _tBase = isStart\n              ? (st.textTimeStartOverride ?? 0.0)\n              : (st.textTimeEndOverride ?? _dur);\n          _tAccum = 0;\n          HapticFeedback.selectionClick();\n        },\n        onHorizontalDragUpdate: (d) {\n          _tAccum += d.delta.dx;\n          _moveTypedEdge(isStart);\n        },\n        child: _handleBody(isStart),\n      ),\n    );\n  }\n\n  void _moveTypedEdge(bool isStart) {\n    var target = _tBase + _tAccum / _pps;\n    final snaps = <double>[\n      widget.controller.value.position.inMilliseconds / 1000.0,\n      ...widget.markers,\n      0,\n      _dur,\n    ];\n    final tol = _snap ? 8 / _pps : -1.0;\n    for (final x in snaps) {\n      if ((x - target).abs() <= tol) {\n        target = x;\n        break;\n      }\n    }\n    target = target.clamp(0.0, _dur).toDouble();\n    if (isStart) {\n      widget.state.setTextWindow(_dur, start: target);\n    } else {\n      widget.state.setTextWindow(_dur, end: target);\n    }\n  }\n\n"""\n\n# ------------------------------------------------------------------- home\nHOME_IMPORT_OLD = "import \'../widgets/pro_transform.dart\'; // PATCH_S180_TRANSFORM\\n"\nHOME_IMPORT_NEW = HOME_IMPORT_OLD + "import \'../services/ruh_touch.dart\'; // " + MARK + "\\n"\n\nHOME_ANYSEL_OLD = "  bool get _hasAnySel => _hasSelSeg || _hasSelCue || _hasSelMain;\\n"\nHOME_ANYSEL_NEW = "  bool get _hasAnySel =>\\n      _hasSelSeg || _hasSelCue || _hasSelMain || state.stageTextSelected; // " + MARK + "\\n"\n\nHOME_DISPATCH_OLD = "    if (!_hasSelSeg) return _clipBar(_hasSelCue ? _cueItems() : _mainItems());\\n"\nHOME_DISPATCH_NEW = (\n    "    // " + MARK + ": the text on the stage / its block on the timeline has a text bar\\n"\n    "    if (state.stageTextSelected && !_hasSelSeg) return _clipBar(_textItems());\\n"\n    + HOME_DISPATCH_OLD)\n\nHOME_WIRE_OLD = """          onSelectSeg: (i) => setState(() {\n            _selSeg = i;\n            _selCue = -1;\n            _selMain = false;\n          }),\n"""\nHOME_WIRE_NEW = """          onSelectSeg: (i) {\n            state.clearStageSelection(); // PATCH_S183_TEXT_BAR\n            setState(() {\n              _selSeg = i;\n              _selCue = -1;\n              _selMain = false;\n            });\n          },\n"""\n\nHOME_TICK_OLD = """    final controller = _video;\n    if (!state.timelineActive ||\n        controller == null ||\n        !controller.value.isInitialized) {\n      return;\n    }\n    final t = controller.value.position.inMilliseconds / 1000.0;\n    // PATCH_S83_SYNC_QOL: loop-one-ayah"""\nHOME_TICK_NEW = """    final controller = _video;\n    if (!state.timelineActive ||\n        controller == null ||\n        !controller.value.isInitialized) {\n      _gateTypedText(controller); // PATCH_S183_TEXT_BAR\n      return;\n    }\n    final t = controller.value.position.inMilliseconds / 1000.0;\n    // PATCH_S83_SYNC_QOL: loop-one-ayah"""\n\nHOME_MARK_OLD = \'  // ---- آيات tab: the folded "advanced" card -----------------------------------\\n\'\nHOME_METHODS = r"""  // ---------------------------------------------------------------------\n  // PATCH_S183_TEXT_BAR: the text bar of the main screen\n  // ---------------------------------------------------------------------\n\n  /// With a begin / stop window on the typed text, the stage shows the text\n  /// only inside it - through the same fade the export uses. (A single\n  /// invisible "hidden" overlay key lets the stage\'s own transition run.)\n  void _gateTypedText(VideoPlayerController? c) {\n    final s = state.textTimeStartOverride;\n    final e = state.textTimeEndOverride;\n    final cur = _liveOverlay.value;\n    final hiddenNow = cur != null && cur.segmentKey == \'hidden-window\';\n    if (c == null ||\n        !c.value.isInitialized ||\n        s == null ||\n        e == null ||\n        state.timelineActive ||\n        !state.hasAyah) {\n      if (hiddenNow) _liveOverlay.value = null;\n      return;\n    }\n    final t = c.value.position.inMilliseconds / 1000.0;\n    final inside = t >= s && t < e;\n    if (!inside && !hiddenNow) {\n      _liveOverlay.value = StageOverlayText(\' \', \'\', \'hidden-window\', null, 0, \'\');\n    } else if (inside && hiddenNow) {\n      _liveOverlay.value = null;\n    }\n  }\n\n  double get _clipLenSec {\n    final c = _video;\n    if (c == null || !c.value.isInitialized) return state.videoDurationSec;\n    return c.value.duration.inMilliseconds / 1000.0;\n  }\n\n  List<(IconData, String, VoidCallback, bool)> _textItems() {\n    final synced = state.timelineActive && state.timeline.isNotEmpty;\n    final hasWin = state.textTimeStartOverride != null &&\n        state.textTimeEndOverride != null;\n    return [\n      (\n        Icons.check_circle_outline,\n        \'تم\',\n        () {\n          state.clearStageSelection();\n          setState(() {\n            _selMain = false;\n            _selCue = -1;\n          });\n        },\n        false\n      ),\n      (Icons.text_decrease, \'أصغر\', () => _nudgeTextSize(-0.1), false),\n      (Icons.text_increase, \'أكبر\', () => _nudgeTextSize(0.1), false),\n      (Icons.font_download_outlined, \'الخط\', _openFontSheet, false),\n      (Icons.vertical_align_center, \'الموضع\', _cycleTextPos, false),\n      (Icons.animation, \'انتقال\', _openTransitionSheet, false),\n      if (!synced) ...[\n        (Icons.first_page, \'يبدأ هنا\', () => _setTextWindowHere(start: true), hasWin),\n        (Icons.last_page, \'ينتهي هنا\', () => _setTextWindowHere(start: false), hasWin),\n        if (hasWin) ...[\n          (Icons.restart_alt, \'كامل المدة\', _resetTextWindow, false),\n        ],\n      ],\n      (Icons.auto_awesome, \'الروح\', _applyRuhNow, false),\n    ];\n  }\n\n  void _nudgeTextSize(double d) {\n    final v = (state.textUserScale + d).clamp(0.4, 3.0).toDouble();\n    HapticFeedback.selectionClick();\n    state.update(() => state.textUserScale = v);\n  }\n\n  void _cycleTextPos() {\n    const vs = AyahTextPosition.values;\n    final n = vs[(state.textPosition.index + 1) % vs.length];\n    HapticFeedback.selectionClick();\n    state.update(() => state.textPosition = n);\n    _toast(switch (n) {\n      AyahTextPosition.top => \'النص في الأعلى\',\n      AyahTextPosition.center => \'النص في الوسط\',\n      AyahTextPosition.bottom => \'النص في الأسفل\',\n    });\n  }\n\n  void _setTextWindowHere({required bool start}) {\n    final dur = _clipLenSec;\n    if (dur <= 0.3) return;\n    final t = _playheadSec;\n    HapticFeedback.mediumImpact();\n    state.pushHistory();\n    state.setTextWindow(dur, start: start ? t : null, end: start ? null : t);\n  }\n\n  void _resetTextWindow() {\n    HapticFeedback.selectionClick();\n    state.pushHistory();\n    state.clearTextWindow();\n    if (_liveOverlay.value?.segmentKey == \'hidden-window\') {\n      _liveOverlay.value = null;\n    }\n  }\n\n  void _applyRuhNow() {\n    final text = _liveOverlay.value?.segmentKey == \'hidden-window\'\n        ? state.ayahText\n        : (_liveOverlay.value?.text ?? state.ayahText);\n    RuhTouch.apply(context, state, text);\n  }\n\n  void _openFontSheet() {\n    HapticFeedback.selectionClick();\n    showModalBottomSheet<void>(\n      context: context,\n      backgroundColor: AyatColors.surface,\n      isScrollControlled: true,\n      shape: const RoundedRectangleBorder(\n          borderRadius: BorderRadius.vertical(top: Radius.circular(22))),\n      builder: (ctx) => SafeArea(\n        child: ListenableBuilder(\n          listenable: state,\n          builder: (context, _) => ConstrainedBox(\n            constraints: BoxConstraints(\n                maxHeight: MediaQuery.of(ctx).size.height * 0.6),\n            child: SingleChildScrollView(\n              padding: const EdgeInsets.fromLTRB(16, 14, 16, 20),\n              child: Column(\n                crossAxisAlignment: CrossAxisAlignment.stretch,\n                children: [\n                  Text(\'اختر الخط\',\n                      style: Theme.of(ctx).textTheme.headlineMedium),\n                  const SizedBox(height: 10),\n                  Wrap(\n                    spacing: 8,\n                    runSpacing: 8,\n                    children: [\n                      for (final f in state.allFonts)\n                        ChoiceChip(\n                          label: Text(_t(f.label),\n                              style: ayahTextStyle(f.key, fontSize: 17)),\n                          selected: state.fontKey == f.key,\n                          onSelected: (_) =>\n                              state.update(() => state.fontKey = f.key),\n                        ),\n                    ],\n                  ),\n                ],\n              ),\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n\n"""\n\nSTAGE_OLD = "(gestureStartUserScale * details.scale).clamp(0.6, 1.8);"\nSTAGE_NEW = "(gestureStartUserScale * details.scale).clamp(0.4, 3.0); // " + MARK\n\nEDITS = {\n  \'state\': [(\'text window methods\', STATE_OLD, STATE_NEW)],\n  \'tl\': [(\'text lane visibility\', TL_LANE_OLD, TL_LANE_NEW)],\n  \'home\': [\n    (\'ruh import\', HOME_IMPORT_OLD, HOME_IMPORT_NEW),\n    (\'any selection\', HOME_ANYSEL_OLD, HOME_ANYSEL_NEW),\n    (\'bar dispatch\', HOME_DISPATCH_OLD, HOME_DISPATCH_NEW),\n    (\'timeline select wiring\', HOME_WIRE_OLD, HOME_WIRE_NEW),\n    (\'preview follows window\', HOME_TICK_OLD, HOME_TICK_NEW),\n    (\'text bar methods\', HOME_MARK_OLD, HOME_METHODS + HOME_MARK_OLD),\n  ],\n  \'stage\': [(\'wider pinch range\', STAGE_OLD, STAGE_NEW)],\n}\nbad = []\nfor k, eds in EDITS.items():\n    for label, old, _ in eds:\n        n = T[k].count(old)\n        if n != 1:\n            bad.append(\'%s: %s (found %d)\' % (F[k], label, n))\na = \'  Widget _textLane(double h, double w) {\'\nb = \'  Widget _cueClip(int i, double h) {\'\nif T[\'tl\'].count(a) != 1 or T[\'tl\'].count(b) != 1 or T[\'tl\'].index(a) > T[\'tl\'].index(b):\n    bad.append(\'%s: text lane anchors\' % F[\'tl\'])\nif bad:\n    sys.exit(\'Anchor check failed, nothing written:\\n  \' + \'\\n  \'.join(bad))\n\nfor k, eds in EDITS.items():\n    for label, old, new in eds:\n        T[k] = T[k].replace(old, new, 1)\n        print(\'  PATCHED\', F[k].split(\'/\')[-1], \'-\', label)\ni, j = T[\'tl\'].index(a), T[\'tl\'].index(b)\nT[\'tl\'] = T[\'tl\'][:i] + TL_TEXTLANE + T[\'tl\'][j:]\nprint(\'  PATCHED pro_timeline.dart - text block on the timeline\')\nfor k, p in F.items():\n    open(p, \'w\', encoding=\'utf-8\').write(T[k])\nprint(\'S183 applied. Next: git add -A && git commit -m "S183: text bar + text block on timeline" && git push\')\n')]
for name, src in PARTS:
    print('== ' + name)
    try:
        exec(compile(src, name, 'exec'), {'__name__': '__main__'})
    except SystemExit as e:
        if e.code not in (None, 0):
            print(e.code); print('Stopped at ' + name + '; nothing after it was applied.'); sys.exit(1)
print('Both applied. Next: git add -A && git commit -m "S182+S183: whisper on main, text bar + text block" && git push')
